#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <sstream>
using namespace std;

static long long popsum(const vector<int>& v) {
    long long t = 0;
    for (size_t i = 0; i < v.size(); i++) {
        int c = v[i];
        while (c) { t += c & 1; c >>= 1; }
    }
    return t;
}

static string run_case(const char* exe, const string& input, int idx) {
    char inf[128], outf[128];
    snprintf(inf, sizeof inf, "l3a2506p1_in%d.txt", idx);
    snprintf(outf, sizeof outf, "l3a2506p1_out%d.txt", idx);
    FILE* f = fopen(inf, "w");
    if (!f) return "";
    fputs(input.c_str(), f);
    fclose(f);
    char cmd[512];
    snprintf(cmd, sizeof cmd, "\"%s\" < %s > %s 2>/dev/null", exe, inf, outf);
    system(cmd);
    string out;
    FILE* o = fopen(outf, "r");
    if (o) {
        char buf[4096];
        size_t r;
        while ((r = fread(buf, 1, sizeof buf, o)) > 0) out.append(buf, r);
        fclose(o);
    }
    remove(inf);
    remove(outf);
    return out;
}

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <candidate-exe>\n", argv[0]); return 2; }
    const char* exe = argv[1];
    vector<vector<int> > cases;
    {
        int a1[] = {71, 69, 83, 80};
        cases.push_back(vector<int>(a1, a1 + 4));
        int a2[] = {1, 2, 4, 8, 16, 32};
        cases.push_back(vector<int>(a2, a2 + 6));
        int a3[] = {0};
        cases.push_back(vector<int>(a3, a3 + 1));
        int a4[] = {255};
        cases.push_back(vector<int>(a4, a4 + 1));
        int a5[] = {255, 1};
        cases.push_back(vector<int>(a5, a5 + 2));
    }
    cases.push_back(vector<int>(100, 255));
    cases.push_back(vector<int>(100, 1));
    unsigned seed = 20250601u;
    for (int t = 0; t < 5; t++) {
        seed = seed * 1103515245u + 12345u;
        int n = 1 + (int)((seed >> 16) % 100);
        vector<int> v;
        for (int j = 0; j < n; j++) {
            seed = seed * 1103515245u + 12345u;
            v.push_back((int)((seed >> 16) % 256));
        }
        cases.push_back(v);
    }
    int pass = 0;
    int total = (int)cases.size();
    for (int i = 0; i < total; i++) {
        ostringstream in;
        in << cases[i].size() << "\n";
        for (size_t j = 0; j < cases[i].size(); j++) in << (j ? " " : "") << cases[i][j];
        in << "\n";
        long long t = popsum(cases[i]);
        char expbuf[64];
        snprintf(expbuf, sizeof expbuf, "%lld %lld", t, t & 1);
        string out = run_case(exe, in.str(), i);
        long long ga = -1, gb = -1;
        istringstream os(out);
        os >> ga >> gb;
        if (ga == t && gb == (t & 1)) pass++;
        else printf("[FAIL] case %d: expected \"%s\", got \"%s\"\n", i + 1, expbuf, out.c_str());
    }
    printf("Results: %d/%d passed\n", pass, total);
    return pass == total ? 0 : 1;
}

