static long long expected(const vector<long long>& v) {
    long long prev = 0, sum = 0;
    for (size_t i = 0; i < v.size(); i++) {
        long long got = prev + 1 > v[i] ? prev + 1 : v[i];
        sum += got;
        prev = got;
    }
    return sum;
}

